function GradientText({
  children: children,
  colors: colors,
  speed = 8,
  sweep = true,
  as: Tag = `span`,
  className: className,
}) {
  let rootRef = React.useRef(null),
    [state, setState] = React.useState(sweep ? `idle` : `in`);
  React.useEffect(() => {
    if (!sweep) return setState(`in`);
    let e = rootRef.current;
    if (!e || typeof IntersectionObserver > `u`) return setState(`in`);
    let t = new IntersectionObserver(
      (e) => {
        e.some((e) => e.isIntersecting) && (setState(`in`), t.disconnect());
      },
      {
        threshold: 0.6,
      },
    );
    return (t.observe(e), () => t.disconnect());
  }, [sweep]);
  let variables = {
    "--ui-gt-speed": `${speed}s`,
  };
  if (colors?.length) {
    let [e, n = e, r = e, i = n] = colors;
    Object.assign(variables, {
      "--ui-gt-c1": e,
      "--ui-gt-c2": n,
      "--ui-gt-c3": r,
      "--ui-gt-c4": i,
    });
  }
  return (
    <Tag
      ref={rootRef}
      className={[`ui-gt`, className].filter(Boolean).join(` `)}
      data-state={state}
      data-sweep={sweep ? `` : void 0}
      style={variables}
    >
      <style href={`ui-gradient-text`} precedence={`default`}>
        {gradientTextStyles}
      </style>
      <span className={`ui-gt__base`}>{children}</span>
      <span className={`ui-gt__fill`} aria-hidden={`true`}>
        {children}
      </span>
    </Tag>
